/* Links do porquê de Estomatologia (Rafael 25/11/2026): afirmação que precisa de explicação. t = trecho exato do texto do site. */
(function(){ var B = window.BANCOS && window.BANCOS.estomato; if (!B) return;
  var MAN = 'Estomatologia para Clínicos da Atenção Básica, SMS-SP 2017 (manual da disciplina)';
  var NEV = 'Neville et al., Patologia Oral e Maxilofacial';
  var INCA = 'INCA, Câncer de boca: manual de detecção de lesões suspeitas, 2ª ed.';
  var OMS = 'Warnakulasuriya et al., consenso OMS das desordens orais potencialmente malignas, Oral Dis 2021';
  var MS = 'Ministério da Saúde, Cadernos de Atenção Básica nº 17: Saúde Bucal (2008), item 4.3.4';
  var KAT = 'Katchburian & Arana, Histologia e Embriologia Oral';
  var GON = 'Gondak RO et al., Lesões pigmentadas da boca, Med Oral Patol Oral Cir Bucal 2012';
  var SPC = 'StatPearls: Oral Candidiasis (NBK545282)';
  var SPH = 'Gopinath D et al., Herpes labial, Viruses 2023';
  var f = function () { return [].slice.call(arguments).join('; '); };
  B.porques = (B.porques || []).concat([

  /* ---------- Lesões brancas ---------- */
  { t: "é um diagnóstico de exclusão", p: "Não existe um exame ou um aspecto que 'prove' a leucoplasia. O dentista chega a ela descartando as outras placas brancas que têm causa conhecida: a candidíase sai na raspagem, a queratose friccional some quando se tira o atrito, a linha alba fica na linha da mordida, o leucoedema some ao esticar. O que sobra, sem explicação, recebe o nome de leucoplasia e vai para biópsia. Ex.: placa branca na bochecha de um fumante que não sai na gaze, não tem dente cortante por perto e não regride: só então se chama de leucoplasia.", fonte: f(INCA, OMS) },
  { t: "Homem acima de 50 anos e fumante reforça", p: "A leucoplasia é ligada ao tabaco, que irrita o epitélio por anos (calor e substâncias químicas da fumaça) e faz a mucosa produzir mais queratina. Como esse efeito depende de tempo de exposição, ela aparece mais em adultos mais velhos, e historicamente mais em homens, que fumavam mais. Ex.: em Petrópolis, um senhor de 58 anos que fuma desde os 20 com placa branca na bochecha é o perfil típico em que a leucoplasia entra na frente das hipóteses de diagnóstico.", fonte: f(INCA, NEV) },
  { t: "candidíase pseudomembranosa SAI na raspagem e deixa base vermelha", p: "Na forma pseudomembranosa, a placa branca é feita de fungos (Candida), células descamadas e restos, apoiada por cima da mucosa, sem fazer parte do epitélio. Por isso a gaze descola a placa. Embaixo, a mucosa está inflamada pela infecção e aparece vermelha. Na leucoplasia, ao contrário, o branco é o próprio epitélio espessado e não sai. Ex.: bebê com 'sapinho': a mãe passa a fralda úmida e as placas saem, deixando a mucosa vermelhinha.", fonte: f(SPC, INCA) },
  { t: "some ao esticar a bochecha", p: "O leucoedema não é uma placa: é o epitélio da bochecha mais grosso e cheio de água (edema dentro das células), que espalha a luz e dá um aspecto leitoso. Quando a mucosa é esticada, as células se afinam e o branco quase desaparece. A leucoplasia é um espessamento de queratina e não muda ao esticar. Ex.: o dentista puxa a bochecha com o espelho clínico e o 'véu' branco some: é variação da normalidade, não precisa de biópsia.", fonte: NEV },
  { t: "só o exame histopatológico mostra se há displasia", p: "Displasia epitelial é uma mudança nas células e na arrumação das camadas do epitélio, que só se vê ao microscópio. Olhando a boca, uma leucoplasia sem displasia e uma com displasia grave podem ter a mesma aparência. Por isso, para saber o risco de virar câncer, é preciso tirar um fragmento na biópsia e mandar para o exame histopatológico. Ex.: duas placas brancas iguais em dois pacientes: o laudo de um vem 'hiperqueratose sem displasia' e o do outro 'displasia moderada'; o controle de cada um muda.", fonte: f(MAN, OMS) },
  { t: "A cor não diz se há displasia", p: "A cor branca vem da quantidade de queratina na superfície, e a displasia está nas camadas de baixo do epitélio, nas células. Uma coisa não depende da outra: placa bem branquinha pode não ter displasia, e placa discreta pode ter. Só a biópsia com exame histopatológico responde. Ex.: o dentista não deve dizer ao paciente 'é só um branco, não é nada'; ele explica que precisa da biópsia para saber.", fonte: f(OMS, MAN) },
  { t: "lesão que não regride em até 3 semanas", p: "Úlceras e placas causadas por trauma, fungo ou vírus costumam melhorar em poucos dias a duas semanas depois que a causa é tirada. Se passou de 3 semanas e a lesão continua, a explicação simples falhou e entra a suspeita de lesão mais séria, inclusive câncer de boca. O prazo serve para não esperar demais: o carcinoma epidermoide descoberto cedo tem tratamento bem mais simples. Ex.: dentista alisou o dente quebrado que machucava a língua; 3 semanas depois a úlcera continua igual: encaminha para biópsia.", fonte: f(MS, INCA) },
  { t: "destruir a lesão sem biópsia apaga o diagnóstico", p: "Se a placa é cauterizada, congelada ou queimada com laser sem tirar um fragmento antes, o tecido que mostraria a displasia ou o câncer é destruído. O patologista fica sem material e a lesão pode voltar sem ninguém saber o que era. Ex.: uma leucoplasia 'queimada' no consultório volta meses depois maior, e agora não há laudo nenhum para dizer se tinha displasia epitelial: perdeu-se tempo e informação.", fonte: f(MAN, OMS) },
  { t: "A Candida albicans vive na boca de muita gente saudável", p: "A Candida é um fungo comensal: faz parte da microbiota normal da boca e fica em equilíbrio com as bactérias e com a defesa do corpo (saliva, imunidade). Encontrar Candida numa pessoa saudável não é doença. Ela só causa candidíase quando esse equilíbrio se quebra. Ex.: num exame de cultura de saliva, uma estudante sem queixa nenhuma pode ter Candida: ela não precisa de antifúngico.", fonte: f(NEV, SPC) },
  { t: "só vira doença quando há um fator facilitador", p: "A Candida é oportunista: para crescer demais e invadir a mucosa, precisa que algo enfraqueça as barreiras. O antibiótico mata as bactérias que competiam com ela; o corticoide e a imunossupressão baixam a defesa; a xerostomia tira a saliva que lava a boca; a prótese dá uma superfície para formar biofilme. Ex.: paciente asmático que usa bombinha de corticoide e não enxágua a boca aparece com placas brancas no palato.", fonte: f(SPC, NEV) },
  { t: "desequilibra a microbiota e favorece a Candida", p: "O antibiótico mata bactérias, inclusive as 'boas' da boca, que ocupavam espaço e consumiam nutrientes. Sem essa competição, a Candida, que é fungo e não morre com antibiótico, cresce à vontade e forma as placas. Ex.: criança que tomou amoxicilina 7 dias para otite aparece com 'língua branca' que sai na gaze: é candidíase pseudomembranosa facilitada pelo antibiótico.", fonte: f(SPC, NEV) },
  { t: "Tratar só o fungo sem achar a causa faz voltar", p: "O antifúngico diminui a quantidade de Candida, mas não corrige o que deixou o fungo crescer. Se o paciente continua com diabetes descompensado, imunossupressão, boca seca ou dormindo com a prótese, a Candida volta a crescer assim que o remédio acaba. Ex.: idosa trata o palato vermelho com nistatina, melhora, mas continua dormindo com a prótese suja: em um mês a estomatite protética voltou.", fonte: f(SPC, MAN) },
  { t: "É uma doença crônica imunomediada", p: "No líquen plano, linfócitos T (células de defesa) atacam por engano as células da camada basal do epitélio. Não é infecção, não pega e não tem uma causa externa que se tire: é o próprio sistema imune que mantém a lesão, com fases de melhora e piora ao longo dos anos. Por isso não há cura, e sim controle. Ex.: paciente com estrias de Wickham há anos, que pioram em época de estresse: o tratamento é acompanhar e usar corticoide quando dói.", fonte: f(NEV, MAN) },
  { t: "costuma não doer", p: "Na forma reticular do líquen plano o epitélio está espessado (as estrias brancas são queratina) e continua inteiro, sem erosão nem úlcera, então as terminações nervosas ficam protegidas. A dor aparece quando o epitélio afina ou se rompe, como na forma erosiva. Ex.: muitos pacientes descobrem o líquen plano reticular só numa consulta de rotina, porque nunca sentiram nada.", fonte: f(NEV, MAN) },
  { t: "Como não há tratamento curativo, o paciente é acompanhado ao longo da vida", p: "Como o líquen plano é mantido pelo próprio sistema imune, os remédios (como o corticoide) só controlam a inflamação, sem eliminar a doença. Além disso, a OMS coloca o líquen plano entre as desordens potencialmente malignas, com risco pequeno de transformação. Por isso o paciente volta periodicamente para o dentista conferir se a lesão mudou de aspecto e se precisa de biópsia. Ex.: consulta a cada 6 meses para comparar a mucosa jugal com as fotos anteriores.", fonte: f(OMS, NEV) },
  { t: "mais comum em quem tem psoríase", p: "A língua geográfica e a psoríase de pele têm um mecanismo parecido: áreas de inflamação em que o epitélio se renova rápido e descama de forma desigual. Estudos brasileiros mostram a língua geográfica bem mais frequente em pacientes com psoríase, e alguns autores a chamam de 'psoríase da língua'. Ex.: ao ver língua geográfica, vale perguntar na anamnese se o paciente tem placas descamando na pele, nos cotovelos ou no couro cabeludo.", fonte: 'Picciani BL et al., Língua geográfica e psoríase, An Bras Dermatol 2016' },
  { t: "Pode coexistir com língua fissurada", p: "As duas são variações do dorso da língua e aparecem juntas com frequência: muitos autores acham que a língua geográfica de longa duração deixa a língua fissurada com o tempo, e as duas compartilham fatores genéticos. Não são doenças graves e nenhuma delas precisa de biópsia. Ex.: paciente com sulcos fundos na língua e, por cima, manchas vermelhas com halo branco que mudam de lugar.", fonte: f('StatPearls: Geographic Tongue (NBK554466)', NEV) },
  { t: "não precisa de tratamento quando não dói", p: "A língua geográfica é benigna: não vira câncer, não é infecção e some e reaparece sozinha. Tratar sem sintoma não traz nenhum ganho. Quando arde, o que se faz é aliviar: evitar ácidos e picantes nas crises e, se precisar, um corticoide ou anestésico tópico. Ex.: jovem que viu as 'manchas de mapa' só no espelho e não sente nada: o dentista explica, tranquiliza e acompanha.", fonte: f('StatPearls: Geographic Tongue (NBK554466)', MAN) },
  { t: "o desenho de mapa que muda de lugar é a pista", p: "As áreas vermelhas da língua geográfica são lugares onde as papilas filiformes descamaram, e o halo branco é a borda onde o epitélio está se renovando. Como esse processo vai 'andando' pelo dorso da língua em dias, o desenho muda. Nenhuma lesão perigosa (como a eritroplasia) migra assim: ela fica fixa no mesmo lugar. Ex.: o dentista fotografa a língua e, na volta em uma semana, as manchas estão em outro ponto: diagnóstico clínico confirmado.", fonte: f('StatPearls: Geographic Tongue (NBK554466)', MAN) },
  { t: "variação comum que aumenta com a idade", p: "A língua fissurada tem base genética, mas os sulcos vão ficando mais fundos e numerosos com os anos, à medida que a mucosa do dorso da língua perde elasticidade. Por isso é bem mais vista em adultos e idosos que em crianças. Ex.: na mesma família, a avó tem a língua cheia de sulcos e a neta de 8 anos só um sulco discreto no meio.", fonte: f('Ehsan H et al., Língua fissurada, Clin Cosmet Investig Dent 2023', MAN) },
  { t: "resto de comida e biofilme se acumulam nos sulcos", p: "Os sulcos da língua fissurada são fundos (às vezes mais de 2 mm) e a escovação comum não chega lá. Restos de comida, células descamadas e bactérias ficam presos e formam biofilme, que fermenta e solta compostos de enxofre: daí o mau hálito, às vezes uma ardência. A solução é mecânica: escovar ou raspar o dorso da língua. Ex.: paciente com língua fissurada e halitose melhora em dias só com o raspador de língua todo dia.", fonte: f('Ehsan H et al., Língua fissurada, Clin Cosmet Investig Dent 2023', NEV) },
  { t: "só se remove se atrapalhar uma prótese", p: "O tórus é osso normal, só que em excesso: não cresce de forma agressiva, não vira tumor e não dói. Operar sem motivo é expor o paciente a uma cirurgia de osso sem ganho. O motivo aparece quando a prótese precisa apoiar ou passar por ali, ou quando a mucosa fina que o cobre machuca toda hora ao comer. Ex.: senhora que vai fazer prótese total superior com um tórus palatino grande: remove-se para a base da prótese assentar.", fonte: f(MAN, 'Sathya K et al., Tórus, J Oral Biol Craniofac Res 2012') },
  { t: "tumor de glândula salivar costuma ser LATERAL", p: "O palato duro tem muitas glândulas salivares menores, mas elas ficam nas laterais e na parte de trás; bem na linha média, onde os dois lados do palato se juntaram no embrião, quase não há glândula. Já o tórus palatino nasce justamente dessa linha de união dos ossos. Por isso um nódulo ao lado da linha média faz pensar em tumor de glândula salivar, e um bem no meio, em tórus. Ex.: nódulo firme a 1 cm da linha média, de crescimento lento: biópsia para afastar adenoma pleomórfico.", fonte: f(NEV, INCA) },
  { t: "quase sempre bilateral, na lingual da região de pré-molares", p: "O tórus mandibular é uma exostose que se forma onde a mandíbula recebe muita força da mastigação, principalmente na face lingual dos pré-molares; como a força é dos dois lados, ele tende a aparecer nos dois. Há também componente genético e relação com apertamento dos dentes (bruxismo). Ex.: paciente que range os dentes à noite com dois 'carocinhos' duros na lingual da mandíbula, iguais dos dois lados.", fonte: f('Sathya K et al., Tórus, J Oral Biol Craniofac Res 2012', MAN) },
  { t: "some sozinha em 1 a 2 semanas sem cicatriz", p: "A afta menor é rasa: a perda do epitélio não chega fundo no tecido conjuntivo. O corpo cobre a ferida com fibrina e o epitélio cresce das bordas para o centro em poucos dias, sem formar cicatriz. A afta maior, por ser mais funda, demora meses e pode deixar cicatriz. Ex.: estudante com afta no lábio na semana de prova: dói uns dias, some em 10 dias e não deixa marca.", fonte: f('StatPearls: Recurrent Aphthous Stomatitis (NBK431059)', MAN) },
  { t: "dentro da boca, prefere mucosa queratinizada", p: "No herpes recorrente intraoral, o vírus reativado desce pelo nervo e sai na mucosa que está presa ao osso, que é a mucosa queratinizada (gengiva inserida e palato duro). Já a afta aparece na mucosa não queratinizada e móvel. Isso ajuda a separar as duas úlceras só pelo lugar. Ex.: depois de uma anestesia no palato, aparecem vesículas agrupadas no palato duro que viram úlceras pequenas: pensar em herpes recorrente, não em afta.", fonte: f(SPH, NEV) },
  { t: "só depois dar o nome evita chute", p: "Quando o aluno descreve primeiro (lesão fundamental, cor, borda, superfície, local), ele junta pistas objetivas, e cada pista elimina hipóteses. Quem dá nome logo de cara costuma se agarrar à primeira ideia e ignorar o que não combina. É o mesmo raciocínio que o manual da disciplina usa: as lesões são agrupadas pelo aspecto. Ex.: 'úlcera rasa, fundo amarelado, halo vermelho, na mucosa do lábio' já leva à afta sem adivinhação; 'mancha' não ajudaria em nada.", fonte: f(MAN, INCA) },
  { t: "O vírus fica latente no gânglio nervoso e reativa", p: "Na primeira infecção, o herpes simples sobe pelos nervos sensitivos e se esconde nos neurônios do gânglio do trigêmeo, onde o sistema imune não o elimina. Quando a defesa local cai (sol, febre, estresse, menstruação), ele volta a se multiplicar, desce pelo mesmo nervo e forma vesículas sempre na mesma região. Ex.: a moça que tem herpes sempre no mesmo canto do lábio depois de um dia de praia.", fonte: f(SPH, MAN) },
  { t: "gatilhos (sol, estresse, febre)", p: "Esses fatores baixam a defesa local ou geral: a radiação ultravioleta do sol diminui a imunidade na pele do lábio, o estresse e a febre mexem com o sistema imune. Com a defesa mais baixa, o herpes simples latente consegue reativar. Saber o gatilho ajuda a prevenir com protetor labial e a começar o antiviral antes de aparecer a vesícula. Ex.: paciente de Petrópolis que sempre tem herpes depois de um fim de semana na praia passa a usar protetor labial com FPS.", fonte: f(SPH, NEV) },
  { t: "o antiviral funciona melhor se começar no formigamento", p: "O aciclovir impede o vírus do herpes simples de copiar o DNA, ou seja, freia a multiplicação. A multiplicação é intensa no começo, nas primeiras horas (fase de formigamento e vesícula). Se o remédio começa só quando já há crosta, o vírus já se multiplicou e a lesão já está cicatrizando: o ganho é pequeno. Ex.: paciente que sente o formigamento de manhã e já passa o aciclovir tem lesão menor e mais curta.", fonte: f(SPH, MAN) },
  { t: "é contagioso, sobretudo na fase de vesícula", p: "O líquido das vesículas do herpes simples está cheio de vírus. Quando a vesícula rompe, esse líquido passa por contato direto (beijo, copo, toalha, dedos). Na crosta ainda há vírus, mas bem menos, e depois de cicatrizar o risco cai muito. Ex.: o dentista adia o atendimento eletivo de um paciente com vesículas no lábio, porque o aerossol e o toque podem levar o vírus até o próprio dentista (herpes no dedo).", fonte: f(SPH, NEV) },
  { t: "mexer nas bolhas espalha o vírus", p: "Ao estourar ou cutucar as vesículas, o líquido cheio de vírus vai para os dedos e daí para outras áreas (olho, outros pontos do lábio) ou outras pessoas. Romper a bolha também abre a porta para bactérias e atrasa a cicatrização. Ex.: criança com herpes que coça o lábio e depois o olho pode ter herpes ocular, que é grave.", fonte: f(SPH, NEV) },

  /* ---------- Nódulos e reacionais ---------- */
  { t: "hormônios da gestação favorecem", p: "Na gravidez, o estrogênio e a progesterona aumentam muito e deixam os vasos da gengiva mais dilatados e permeáveis, e a resposta inflamatória ao biofilme fica exagerada. Com um irritante local (biofilme, cálculo), forma-se tecido de granulação em excesso: o granuloma piogênico, apelidado de 'granuloma gravídico'. Ex.: gestante no 2º trimestre, com gengivite, aparece com um nódulo vermelho entre dois dentes que sangra ao escovar.", fonte: f('StatPearls: Pyogenic Granuloma (NBK556077)', MAN) },
  { t: "O nome engana: não tem pus nem é granuloma de verdade", p: "O nome 'piogênico' (que forma pus) vem de quando se achava que era uma infecção. Ao microscópio não há pus nem o granuloma verdadeiro (aquele grupo de macrófagos da tuberculose): há tecido de granulação, cheio de vasos novos. É uma lesão reacional, não infecciosa. Ex.: no laudo histopatológico vem 'proliferação vascular lobular', e o aluno estranha por não ver pus nenhum.", fonte: f(NEV, 'StatPearls: Pyogenic Granuloma (NBK556077)') },
  { t: "O local mais comum é a gengiva", p: "O granuloma piogênico é uma reação a irritante local, e é na gengiva que mais se acumulam biofilme e cálculo, além de bordas de restauração mal adaptadas. Por isso ele aparece mais ali, sobretudo na gengiva vestibular da maxila. Ex.: paciente com cálculo grande na região de pré-molares superiores aparece com um nódulo vermelho na papila: remove-se a lesão e o cálculo.", fonte: f(MAN, NEV) },
  { t: "por isso é vermelho e sangra ao toque", p: "A lesão é formada por muitos capilares novos, com parede fina e pouco tecido de apoio em volta, numa superfície muitas vezes ulcerada. A cor vermelha é o sangue visto através de uma camada fina; qualquer toque rompe esses vasos frágeis. Ex.: ao passar a sonda periodontal, o granuloma piogênico sangra na hora, enquanto o fibroma ao lado, de colágeno, nem sangra.", fonte: f(NEV, MAN) },
  { t: "uma das lesões reacionais mais comuns da boca", p: "Mordiscar a bochecha ou o lábio é muito comum, e cada mordida machuca um pouco a mucosa. O corpo responde produzindo colágeno para reparar, e com o trauma repetido esse colágeno vai se acumulando num nódulo: o fibroma traumático. Como o hábito é frequente, a lesão também é. Ex.: em levantamentos de biópsias brasileiras, o fibroma está sempre entre as lesões mais diagnosticadas.", fonte: f('Lakkam BD et al., Lesões reacionais focais, J Oral Maxillofac Pathol 2020', NEV) },
  { t: "O fibroma traumático não regride sozinho", p: "O fibroma é feito de colágeno denso, que é tecido de cicatriz e não inflamação passageira. Inflamação vai embora quando a causa some; colágeno depositado fica. Por isso, mesmo parando de morder, o nódulo fica, e o tratamento é remover com biópsia excisional. Ex.: paciente parou de morder o lábio há meses e o nódulo continua igual: só a cirurgia resolve.", fonte: f(MAN, NEV) },
  { t: "corrige-se o trauma (mordida, dente, prótese) para não voltar", p: "Tirar o fibroma traumático resolve o nódulo, mas se o dente cortante, a prótese ou o hábito de morder continuarem, o mesmo trauma volta a estimular colágeno no mesmo lugar, e a lesão recidiva. Ex.: após remover o fibroma da bochecha, o dentista alisa a cúspide afiada do molar que batia ali e orienta o paciente sobre o hábito.", fonte: f(MAN, NEV) },

  /* ---------- Glândulas salivares ---------- */
  { t: "geralmente da glândula sublingual", p: "A glândula sublingual fica bem embaixo da mucosa do assoalho e solta saliva o tempo todo, por vários ductos pequenos. Quando um ducto rompe, o muco vaza continuamente para o tecido e forma a rânula. Por isso o tratamento muitas vezes inclui retirar a sublingual: senão, ela continua produzindo e a lesão volta. Ex.: rânula que recidiva duas vezes após drenagem, até o cirurgião remover a glândula sublingual junto.", fonte: f('StatPearls: Mucocele and Ranula (NBK560855)', NEV) },
  { t: "O lábio inferior é o local mais comum", p: "O lábio inferior é cheio de glândulas salivares menores logo abaixo da mucosa e é o lugar que mais levamos mordida (e pancada). O trauma rompe um ducto, o muco extravasa e forma a mucocele. No lábio superior ela é rara; ali, nódulo parecido faz pensar mais em tumor de glândula salivar. Ex.: adolescente que mordeu o lábio comendo e dias depois tem uma bolha azulada: mucocele típica.", fonte: f(MAN, 'StatPearls: Mucocele and Ranula (NBK560855)') },
  { t: "junto com as glândulas menores vizinhas", p: "Se o cirurgião tira só a bolha de muco, as glândulas salivares menores ao lado continuam produzindo, e o ducto lesado ou outro vizinho pode voltar a vazar: a mucocele recidiva. Retirando as glândulas próximas, acaba a fonte de muco. Por isso drenar com agulha não resolve. Ex.: mucocele furada em casa com alfinete esvazia e enche de novo em uma semana.", fonte: f(MAN, NEV) },

  /* ---------- Pigmentadas ---------- */
  { t: "acúmulo de queratina que não descama", p: "Normalmente as papilas filiformes têm uma ponta de queratina que vai sendo gasta pela comida e pela língua roçando no palato. Com dieta mole, pouca higiene, fumo ou antibiótico, essa descamação diminui e a queratina vai se empilhando: as papilas ficam até 10 vezes mais compridas, parecendo pelos. Ex.: paciente em dieta líquida por semanas depois de cirurgia desenvolve língua pilosa.", fonte: f('Gurvits GE, Tan A, Língua pilosa negra, World J Gastroenterol 2014', NEV) },
  { t: "pegam cor de bactérias, fumo, café e chá", p: "As papilas compridas funcionam como um tapete que segura o que passa pela boca. Pigmentos do café, chá e tabaco grudam na queratina, e bactérias cromogênicas (que fabricam pigmento) crescem ali. A cor final depende do que predomina: amarela, marrom ou preta. Ex.: o mesmo paciente com língua pilosa branca fica com ela preta depois de semanas tomando muito café e fumando.", fonte: f(GON, 'Gurvits GE, Tan A, Língua pilosa negra, World J Gastroenterol 2014') },
  { t: "É benigna e reversível", p: "A língua pilosa é só queratina acumulada e corada, sem alteração das células nem risco de câncer. Quando o paciente escova ou raspa o dorso da língua e corta os fatores (fumo, antibiótico sem necessidade), as papilas voltam ao tamanho normal em poucas semanas. Ex.: fumante que passa a usar raspador de língua todo dia vê a língua clarear em 2 a 3 semanas.", fonte: f('Gurvits GE, Tan A, Língua pilosa negra, World J Gastroenterol 2014', MAN) },
  { t: "A radiografia às vezes mostra as partículas radiopacas", p: "O amálgama é metálico e barra o raio X, então partículas grandes o suficiente aparecem como pontinhos brancos (radiopacos) na periapical. Partículas muito pequenas ou espalhadas podem não aparecer, por isso o 'às vezes'. Quando aparecem, confirmam a tatuagem por amálgama e afastam o melanoma. Ex.: mancha azulada no rebordo e, na periapical, pontinhos brancos no mesmo lugar: diagnóstico fechado sem biópsia.", fonte: f(MAN, 'Sasaki R et al., Tatuagem por amálgama, CMAJ 2023') },
  { t: "uma das pigmentações localizadas mais comuns da boca", p: "Durante décadas o amálgama foi a restauração mais usada, e em cada restauração, polimento ou extração pequenas partículas podem entrar na mucosa ferida. O metal fica ali para sempre, preso no tecido conjuntivo, e escurece por oxidação. Por isso, em adultos com restaurações antigas, a tatuagem por amálgama é muito frequente. Ex.: idoso com mancha azul-acinzentada na gengiva ao lado de uma restauração de amálgama de 30 anos.", fonte: f(GON, NEV) },
  { t: "hematoma some em dias", p: "No hematoma, o sangue que saiu do vaso é absorvido pelo corpo: macrófagos 'comem' as hemácias e a hemoglobina vai sendo degradada (por isso a cor muda de roxo para verde e amarelo) até sumir em uma ou duas semanas. Já o amálgama é metal e não é absorvido, então a mancha da tatuagem por amálgama é permanente. Ex.: mancha roxa depois de uma anestesia que desapareceu em 10 dias não era tatuagem.", fonte: f(NEV, GON) },

  /* ---------- Semiologia ---------- */
  { t: "rompem (viram úlceras/erosões) e depois fazem crosta", p: "A vesícula do herpes é uma bolha muito fina dentro do epitélio; o atrito e a própria inflamação rompem o teto rapidamente, deixando uma úlcera ou erosão. No vermelhão do lábio, que é seco, o líquido e a fibrina secam e formam crosta; dentro da boca, úmida, fica só a úlcera. Ex.: no 1º dia o paciente vê bolhinhas no lábio, no 3º elas estouraram e no 5º há uma casquinha.", fonte: f(SPH, MAN) },

  /* ---------- Vermelhas e câncer ---------- */
  { t: "a forma mosqueada tem maior potencial de malignização que a homogênea", p: "As áreas vermelhas da leucoplasia mosqueada são pontos onde o epitélio está mais fino e com células alteradas, ou seja, onde a displasia epitelial costuma estar. A forma homogênea, lisa e toda branca, mais vezes é só queratina a mais. Estudos e o consenso da OMS mostram que a não homogênea vira câncer bem mais vezes. Ex.: duas leucoplasias no mesmo serviço: a mosqueada vai para biópsia e controle mais apertado.", fonte: f(INCA, OMS) },
  { t: "a eritroplasia é a que mais vem com displasia grave ou carcinoma", p: "Na eritroplasia, a cor vermelha aparece porque o epitélio está fino e atrófico, deixando ver os vasos do tecido conjuntivo, e esse epitélio fino quase sempre tem células muito alteradas. Por isso, quando se biopsia, a maioria já é displasia grave, carcinoma in situ ou carcinoma invasivo. Ex.: placa vermelha aveludada no assoalho de um fumante: biópsia na hora, sem esperar.", fonte: f(INCA, 'Lorenzo-Pouso AI et al., Eritroplasia oral, J Oral Pathol Med 2022') },
  { t: "de preferência da área vermelha", p: "Numa lesão branca e vermelha, a parte vermelha é onde o epitélio está mais fino e com mais displasia epitelial. Se o fragmento for tirado só do branco, o laudo pode vir 'sem displasia' e enganar, porque a parte pior ficou de fora. Ex.: na biópsia incisional de uma eritroleucoplasia, o dentista tira o fragmento pegando a área vermelha e a transição com o branco.", fonte: f(INCA, MAN) },
  { t: "palpação dos linfonodos do pescoço", p: "O carcinoma epidermoide da boca se espalha primeiro pela drenagem linfática, indo para os linfonodos do pescoço. Um linfonodo duro, fixo e indolor pode indicar metástase, o que muda o estadiamento e o tratamento. Como isso pode acontecer sem dor, só a palpação descobre. Ex.: ao examinar um fumante com úlcera na borda da língua, o dentista palpa a região submandibular e cervical e anota qualquer linfonodo endurecido no encaminhamento.", fonte: f(INCA, NEV) },
  { t: "Local de risco (borda lateral da língua)", p: "A borda lateral e o ventre da língua e o assoalho têm mucosa fina e não queratinizada, e são as áreas onde a saliva com as substâncias do tabaco e do álcool fica 'empoçada' mais tempo. O epitélio fino e mais exposto acumula mais dano no DNA. Por isso a maior parte dos carcinomas intraorais aparece ali. Ex.: no exame de rotina, o dentista puxa a língua com gaze para os lados e olha a borda, porque é onde mais se acha câncer de boca.", fonte: f(INCA, NEV) },
  { t: "Sol crônico no lábio inferior provoca queilite actínica", p: "O lábio inferior fica virado para cima e para frente, recebe a luz do sol quase de frente e tem pouca melanina e queratina para se proteger. A radiação ultravioleta, ano após ano, danifica o DNA das células do epitélio e o colágeno embaixo, causando ressecamento, placas brancas e displasia epitelial. Ex.: trabalhador rural da região serrana que passou a vida no sol sem chapéu, com o lábio inferior esbranquiçado e o superior normal.", fonte: f('StatPearls: Actinic Cheilitis (NBK551553)', MAN) },

  /* ---------- Brancas: normalidade ---------- */
  { t: "espessamento de queratina por atrito/sucção da bochecha", p: "Na linha em que os dentes de cima e de baixo se encontram, a mucosa da bochecha é pressionada e sugada contra os dentes o dia todo. O epitélio responde a esse atrito leve e constante produzindo mais queratina, como um calo, e fica branco. Por isso a linha alba só existe onde há dentes. Ex.: paciente que aperta os dentes tem a linha alba mais marcada nas duas bochechas.", fonte: f(MAN, 'McKinney R, Olmo H, Lesões brancas benignas, StatPearls 2024') },
  { t: "mais comum em pessoas negras", p: "O leucoedema é muito frequente em pessoas negras (em alguns estudos, na maioria dos adultos), provavelmente porque o epitélio da bochecha delas é naturalmente mais espesso e com mais água nas células, o que fica ainda mais visível sobre uma mucosa com mais melanina. Fumo também acentua. Ex.: em um homem negro de 35 anos com véu leitoso nas duas bochechas que some ao esticar, o dentista não pede biópsia.", fonte: f(NEV, 'Martin JL, Leucoedema, J Natl Med Assoc 1992') },
  { t: "A leucoplasia NÃO some ao esticar", p: "Na leucoplasia o branco é a queratina grossa presa na superfície do epitélio, e às vezes células alteradas. Esticar a mucosa não muda a quantidade de queratina, então a placa continua lá. No leucoedema, o branco vem de água dentro das células, que se espalha ao esticar. É um teste simples na cadeira. Ex.: placa branca que continua idêntica com a bochecha esticada pelo espelho clínico: não é leucoedema, segue a investigação.", fonte: f(NEV, INCA) },
  { t: "Tirando a causa, ela regride", p: "A queratose friccional é uma defesa: o epitélio engrossa a queratina para aguentar o atrito, como um calo. Se o atrito acaba, o estímulo para fabricar queratina some, a camada vai descamando e a mucosa volta ao normal em semanas (o manual fala em 4 a 6). Se não volta, a lesão não era só atrito e precisa de biópsia. Ex.: ajustado o grampo da prótese parcial, a placa branca some em um mês.", fonte: f(MAN, 'Müller S, Queratose friccional, Head Neck Pathol 2019') },
  { t: "A Candida forma biofilme na base da prótese", p: "A resina acrílica da prótese tem poros e ranhuras microscópicas onde a Candida se prende e forma um biofilme com bactérias. Esse biofilme fica encostado no palato o dia e a noite todos, embaixo de uma prótese que diminui a lavagem pela saliva. Aí a mucosa inflama exatamente no desenho da prótese. Ex.: Dona Maria, que dorme com a dentadura, tem o palato vermelho com o 'carimbo' da prótese: estomatite protética.", fonte: f('Abuhajar E et al., Estomatite protética, Int J Environ Res Public Health 2023', MAN) },
  { t: "a prótese é o reservatório da Candida", p: "O antifúngico age na mucosa, mas a Candida que está no biofilme dentro dos poros da prótese fica protegida. Se a prótese não é escovada, deixada de molho em solução de limpeza e tirada à noite, ela recontamina o palato assim que o remédio acaba. Ex.: paciente trata a estomatite protética só com nistatina e volta com o palato vermelho em semanas, porque nunca limpou a dentadura.", fonte: f('Abuhajar E et al., Estomatite protética, Int J Environ Res Public Health 2023', MAN) },
  { t: "É bem mais rara que a leucoplasia, mas tem risco muito maior", p: "A eritroplasia aparece bem menos que a leucoplasia (proporção de dezenas de leucoplasias para cada eritroplasia), mas, como o vermelho é sinal de epitélio fino e com células muito alteradas, quase todas já são displasia grave ou carcinoma quando biopsiadas. A leucoplasia, mais comum, vira câncer numa parcela bem menor. Ex.: num ano de clínica o dentista vê várias leucoplasias e talvez uma eritroplasia, mas é essa que não pode esperar.", fonte: f(INCA, OMS) },
  { t: "Locais típicos: assoalho, palato mole e borda da língua", p: "São regiões de mucosa não queratinizada e fina, e por onde a saliva carregada de substâncias do tabaco e do álcool escorre e fica parada (assoalho e borda da língua) ou por onde a fumaça passa (palato mole). Epitélio fino e muito exposto acumula mais dano e mais displasia epitelial. Ex.: no exame de um fumante e etilista, o dentista olha com atenção redobrada o assoalho e o palato mole, que os pacientes nunca veem no espelho.", fonte: f(INCA, NEV) },
  { t: "mais melanina, sem aumento de melanócitos", p: "Na mácula melanótica, o número de melanócitos (as células que fabricam o pigmento) é normal; eles só produzem mais melanina, que se deposita na camada basal. Como não há proliferação de células, não é tumor e não cresce. No nevo há acúmulo de melanócitos, e no melanoma eles se multiplicam sem controle. Ex.: mancha marrom no lábio inferior igual há 10 anos: o laudo mostra 'melanina aumentada na camada basal' e só.", fonte: f(GON, NEV) },
  { t: "a borda da língua é local de risco", p: "Mesmo uma úlcera com causa aparente (dente quebrado) na borda da língua merece prazo curto de reavaliação, porque é o local mais frequente do carcinoma epidermoide na boca. Um câncer inicial pode parecer uma úlcera traumática, e o dente cortante pode só ter piorado uma lesão que já existia. Ex.: dentista alisa o molar e marca retorno em 2 a 3 semanas; se a úlcera não sumir, biópsia.", fonte: f(INCA, MS) },
  { t: "Dura cerca de 10 a 14 dias", p: "Na primeira infecção, o corpo ainda não tem anticorpos nem células de defesa 'treinadas' contra o herpes simples. Leva uns dias para a imunidade montar a resposta e controlar o vírus; até lá surgem vesículas e úlceras por toda a boca. Depois a mucosa cicatriza, e o vírus fica latente no gânglio. Ex.: criança de 3 anos com gengivoestomatite herpética melhora a febre em 3 a 4 dias e as úlceras somem em cerca de duas semanas.", fonte: f('StatPearls: Herpetic Gingivostomatitis (NBK526068)', MAN) },
  { t: "A afta não dá febre nem gengivite generalizada", p: "A afta é uma reação imune local, na própria mucosa, sem vírus se espalhando pelo corpo, então não causa febre nem mal-estar e não inflama a gengiva toda. A gengivoestomatite herpética é uma infecção viral que atinge o organismo: dá febre, gânglios e gengiva inteira vermelha e inchada. Ex.: criança com úlceras + febre + gengiva sangrando = pensar em herpes primário, não em afta.", fonte: f('StatPearls: Herpetic Gingivostomatitis (NBK526068)', MAN) },
  { t: "Sem trocar a prótese, volta", p: "A hiperplasia fibrosa inflamatória é uma resposta ao trauma crônico da borda da prótese desadaptada. Se só o excesso de tecido for removido e o paciente continuar usando a mesma prótese, a borda volta a machucar o mesmo ponto e a lesão cresce de novo. Ex.: senhor operado do épulis fissurado que continua com a dentadura de 15 anos: em meses as pregas voltam no fundo de vestíbulo.", fonte: f(MAN, 'González Gómez LA et al., Épulis fissurado, World J Clin Cases 2025') },
  { t: "Na gestação pode diminuir depois do parto", p: "O granuloma piogênico da gestante depende em parte dos hormônios da gravidez, que aumentam a vascularização e a inflamação da gengiva. Depois do parto, os hormônios voltam ao normal e a lesão muitas vezes encolhe sozinha. Por isso, se não atrapalhar, pode-se controlar o biofilme e esperar. Ex.: gestante de 6 meses com lesão pequena faz raspagem e higiene e reavalia depois do parto, evitando cirurgia na gravidez.", fonte: f('StatPearls: Pyogenic Granuloma (NBK556077)', NEV) },
  { t: "glândulas sebáceas fora do lugar habitual", p: "Durante a formação do rosto no embrião, a pele e a mucosa da boca se juntam na região da bochecha e dos lábios, e algumas glândulas sebáceas (que normalmente ficam na pele, junto dos pelos) ficam 'presas' na mucosa. Elas produzem sebo e aparecem como pontinhos amarelos. É normal e não tem risco. Ex.: paciente vê os grânulos de Fordyce depois da puberdade, quando as glândulas sebáceas crescem com os hormônios.", fonte: f(MAN, 'Alamri N et al., Grânulos de Fordyce, J Pharm Bioallied Sci 2024') },
  { t: "não está entre as desordens potencialmente malignas da OMS", p: "A lista da OMS reúne lesões que, em estudos de acompanhamento, viraram câncer mais do que a mucosa normal (leucoplasia, eritroplasia, líquen plano, queilite actínica e outras). A língua geográfica foi estudada e não mostrou esse risco: é inflamação benigna que vai e volta. Por isso biópsia não é rotina. Ex.: paciente com língua geográfica há 20 anos não tem chance maior de câncer de boca por isso.", fonte: f(OMS, 'StatPearls: Geographic Tongue (NBK554466)') },
  { t: "Locais de maior risco: assoalho da boca e ventre/borda da língua", p: "Uma leucoplasia no assoalho ou no ventre/borda da língua tem mais chance de mostrar displasia epitelial e virar câncer que a mesma placa na bochecha. Nessas áreas a mucosa é fina, não queratinizada e banhada pela saliva com carcinógenos do tabaco e do álcool. Ex.: duas leucoplasias homogêneas, uma na bochecha e outra no ventre da língua: a do ventre tem prioridade na biópsia.", fonte: f(INCA, OMS) },
  { t: "o álcool potencializa", p: "O álcool age como solvente: deixa a mucosa mais permeável e ajuda as substâncias cancerígenas do tabaco a entrarem no epitélio. Além disso, o corpo transforma o álcool em acetaldeído, que também danifica o DNA e favorece a displasia epitelial. Juntos, fumo e álcool multiplicam o risco, não só somam. Ex.: quem fuma e bebe todo dia tem risco de câncer de boca muito maior do que quem só fuma ou só bebe.", fonte: f(INCA, NEV) },
  { t: "90 a 95% dos cânceres de boca", p: "Quase toda a mucosa da boca é revestida por epitélio escamoso (pavimentoso estratificado), e é nele que o tabaco, o álcool e o sol causam o dano. Por isso quase todo câncer de boca nasce desse epitélio: o carcinoma epidermoide, também chamado carcinoma espinocelular ou CEC. Os outros (glândula salivar, melanoma, sarcomas, linfomas) são bem mais raros. Ex.: quando um paciente fala 'câncer de boca', em 9 de cada 10 casos é carcinoma epidermoide.", fonte: f(INCA, MAN) },
  { t: "câncer inicial costuma ser indolor", p: "No começo, o carcinoma epidermoide é pequeno e fica na superfície, sem invadir nervos nem linfonodos e sem inflamar muito. A dor aparece quando o tumor cresce, vira uma úlcera grande e infiltra nervos e músculos. Por isso o paciente não procura o dentista por causa dele, e o diagnóstico atrasa. Ex.: o seu Antônio dizia que a ferida na língua 'não doía muito': justamente por isso esperou 2 meses.", fonte: f(INCA, MS) },
  { t: "a exposição solar pesa muito", p: "O lábio inferior não é banhado pela saliva com tabaco como o resto da boca, mas fica exposto à radiação ultravioleta do sol, que causa mutações no epitélio. Por isso o câncer de lábio inferior aparece muito em trabalhadores ao ar livre e pessoas de pele clara, quase sempre depois de anos de queilite actínica. Ex.: pescador de pele clara, sem protetor labial, com úlcera no lábio inferior: o sol é o principal suspeito.", fonte: f(INCA, MAN) },
  { t: "protetor labial com FPS, chapéu", p: "Como a queilite actínica é causada pela radiação ultravioleta acumulada, a primeira medida é parar de acumular: o protetor labial com filtro solar barra a radiação direto na mucosa do lábio, e o chapéu de aba faz sombra no rosto. Assim se evita que a displasia epitelial progrida. Ex.: o José, que trabalha na lavoura, recebe a orientação de passar protetor labial várias vezes ao dia e usar chapéu de aba larga.", fonte: f(MAN, 'StatPearls: Actinic Cheilitis (NBK551553)') },
  { t: "só o exame ativo (inspeção e palpação) pega cedo", p: "Como o câncer de boca inicial não dói, o paciente não reclama dele; e como ele se espalha pelos linfonodos do pescoço sem dor, também não se percebe. A única forma de achar cedo é o dentista procurar: olhar todas as regiões da boca, puxar a língua, apalpar o assoalho e o pescoço em toda consulta. Ex.: paciente vem só para uma restauração e, no exame completo, o dentista acha uma eritroplasia no assoalho.", fonte: f(INCA, MS) },
  { t: "É a forma que mais dói e em que a biópsia é mais indicada", p: "Na forma erosiva do líquen plano, o epitélio fica fino ou some em áreas (erosão), deixando as terminações nervosas expostas: daí a ardência com comida temperada. Além disso, áreas vermelhas e erodidas podem se confundir com eritroplasia ou carcinoma, então a biópsia ajuda a não deixar passar uma lesão maligna. Ex.: mulher com ardência e áreas vermelhas na bochecha: biópsia para confirmar o líquen plano e afastar câncer.", fonte: f(INCA, MAN) },
  { t: "podem confundir com eritroplasia e carcinoma", p: "As três lesões são vermelhas por causa do epitélio fino ou ausente, que deixa ver os vasos do tecido conjuntivo. Só olhando, nem sempre dá para separar uma erosão do líquen plano de uma eritroplasia ou de um carcinoma inicial. Por isso, na dúvida, a biópsia decide. Ex.: área vermelha no assoalho sem as estrias de Wickham típicas: não se fecha 'líquen plano' sem o laudo.", fonte: f(INCA, NEV) },
  { t: "a pele dobra e fica úmida", p: "Quando a prótese está gasta, a boca fecha mais do que deveria (perda de dimensão vertical). A pele dos cantos da boca forma uma dobra funda onde a saliva escorre e fica parada. Pele úmida e macerada é o ambiente ideal para a Candida e bactérias crescerem: surge a queilite angular. Ex.: seu Joaquim, de prótese gasta, melhora das fissuras só quando faz prótese nova e a dobra some.", fonte: f(MAN, SPC) },
  { t: "muitas vezes com bactérias junto", p: "A fissura úmida do canto da boca é colonizada não só pela Candida, mas muitas vezes pelo Staphylococcus aureus que vive na pele e no nariz. Por isso, em alguns casos, só antifúngico não resolve e se usa um creme com antifúngico e antibacteriano. Ex.: queilite angular que não melhorou com nistatina e melhorou com pomada que tem miconazol e antibiótico.", fonte: f(SPC, 'Hellstein JW, Marek CL, Candidíase, Head Neck Pathol 2019') },
  { t: "só a pseudomembranosa sai na raspagem", p: "Só na forma pseudomembranosa o fungo forma placas soltas por cima da mucosa. Na hiperplásica, a Candida invade o epitélio, que engrossa e fica branco e preso (não sai). Na eritematosa (atrófica), o epitélio fica fino e vermelho, sem placa nenhuma. Ex.: palato vermelho embaixo da prótese não tem nada para raspar, mas é candidíase do mesmo jeito.", fonte: f('Hellstein JW, Marek CL, Candidíase, Head Neck Pathol 2019', MAN) },
  { t: "só se separa da leucoplasia pela biópsia", p: "A candidose hiperplásica é uma placa branca que não sai na raspagem, exatamente como a leucoplasia. A diferença está no microscópio: hifas de Candida dentro do epitélio. O manual orienta tratar com antifúngico e, se não regredir, fazer biópsia para descartar displasia epitelial. Ex.: placa branca atrás da comissura que melhora com antifúngico era candidose; a que não melhora vai para biópsia.", fonte: f(MAN, 'Hellstein JW, Marek CL, Candidíase, Head Neck Pathol 2019') },
  { t: "em cerca de 90% dos casos", p: "Este número do INCA vem de séries de biópsias: quando uma placa vermelha sem outra causa é examinada, cerca de 9 em 10 já mostram displasia grave, carcinoma in situ ou carcinoma invasivo. É o maior risco entre as lesões da boca, e por isso a área vermelha merece a biópsia. Ex.: das 10 eritroplasias biopsiadas num serviço, só uma vem sem alteração grave.", fonte: f(INCA, 'Lorenzo-Pouso AI et al., Eritroplasia oral, J Oral Pathol Med 2022') },

  /* ---------- Pigmentadas 2 ---------- */
  { t: "difusas e manterem a textura da mucosa", p: "A pigmentação fisiológica é só mais melanina em melanócitos normais espalhados por toda a gengiva, sem formar massa: a mancha é larga, dos dois lados, e a superfície continua lisa. No melanoma os melanócitos se multiplicam e invadem, formando lesão isolada que pode ficar elevada, irregular e ulcerada. Ex.: faixa marrom igual nas duas hemiarcadas, gengiva com pontilhado normal: pigmentação fisiológica.", fonte: f(INCA, GON) },
  { t: "o melanoma costuma ser mancha isolada, assimétrica, que cresce", p: "O melanoma nasce de um grupo de melanócitos que sofreu mutação e se multiplica sem controle, então começa num ponto só (isolado), cresce mais para um lado do que para o outro (assimétrico) e aumenta com o tempo. É o oposto da pigmentação fisiológica, que é larga, simétrica e estável. Ex.: mancha negra no palato que a filha acha que 'cresceu' em meses: biópsia urgente.", fonte: f(INCA, MAN) },
  { t: "aparece em 25 a 31% dos fumantes", p: "Estudos encontram a melanose do fumante em cerca de um quarto a um terço dos fumantes, porque substâncias da fumaça estimulam os melanócitos da gengiva, como se fosse uma defesa. Quanto mais cigarros por dia, mais pigmento. Ex.: num grupo de 10 fumantes atendidos na clínica da faculdade, 2 ou 3 costumam ter manchas marrons na gengiva vestibular inferior.", fonte: GON },
  { t: "O fumo estimula os melanócitos a produzir mais melanina", p: "Acredita-se que a melanina funcione como proteção, ligando-se a substâncias nocivas da fumaça (como a nicotina e hidrocarbonetos). Em resposta ao tabaco, os melanócitos da mucosa aumentam a produção de pigmento, sem se multiplicar de forma anormal. Por isso é benigno. Ex.: a gengiva anterior inferior, onde a fumaça bate primeiro, é a área mais pigmentada no fumante.", fonte: f(GON, NEV) },
  { t: "a cor tende a clarear aos poucos", p: "Sem o estímulo do tabaco, os melanócitos voltam a produzir a quantidade normal de melanina, e o pigmento que já existia vai sendo eliminado com a renovação lenta do epitélio. Isso leva meses a anos. Se a mancha não clarear ou crescer depois de parar de fumar, vale biópsia. Ex.: paciente que parou de fumar em Petrópolis em janeiro mostra a gengiva visivelmente mais clara no ano seguinte.", fonte: GON },
  { t: "É raro na boca, mas muito agressivo", p: "O melanoma oral é muito menos comum que o carcinoma epidermoide, mas na mucosa ele costuma ser descoberto tarde (ninguém olha o próprio palato), cresce rápido e se espalha cedo pelo sangue e pelos linfonodos. Por isso a sobrevida é baixa. A única defesa é investigar cedo toda mancha suspeita. Ex.: mancha negra no palato de um idoso: o dentista não espera para ver se cresce, faz biópsia ou encaminha na hora.", fonte: f(INCA, MAN) },
  { t: "qualquer que seja o tempo de evolução", p: "Mesmo uma mancha 'antiga' pode ser melanoma: ele pode ficar um tempo crescendo devagar na superfície antes de invadir, e o paciente muitas vezes nem sabe desde quando ela existe. Por isso, em palato, rebordo e gengiva, locais preferidos do melanoma oral, o tempo não tranquiliza. Ex.: paciente diz que a mancha no palato 'sempre esteve lá': mesmo assim vai para biópsia.", fonte: f(INCA, MAN) },
  { t: "o melanoma inicial pode parecer um nevo", p: "No começo o melanoma pode ser pequeno, plano e marrom, igualzinho a um nevo melanocítico benigno. A diferença só aparece no microscópio (células atípicas, invasão). Como o palato é local comum dos dois, a orientação é biopsiar toda pigmentação nova ou sem explicação. Ex.: pápula marrom de 4 mm no palato sem amálgama por perto: biópsia excisional, que já trata se for nevo.", fonte: f(GON, MAN) },
  { t: "Alguns remédios pigmentam a mucosa", p: "Alguns fármacos se depositam no tecido junto com a melanina ou o ferro (minociclina, antimaláricos), e outros estimulam os melanócitos a produzir mais pigmento (zidovudina, cetoconazol). A mancha aparece depois de meses de uso e costuma clarear quando o remédio é suspenso. Por isso a anamnese com a lista de medicamentos é parte da investigação. Ex.: paciente com acne que toma minociclina há meses e aparece com o palato acinzentado.", fonte: f(GON, NEV) },
  { t: "as papilas filiformes ficam compridas porque não descamam", p: "A língua normalmente se 'lixa' na comida e no palato, e a ponta de queratina das papilas filiformes vai saindo. Quando isso falha (dieta mole, pouca escovação, fumo, boca seca), a queratina se acumula e as papilas ficam longas, prendendo o que passa. Ex.: idoso que só come sopa e não escova a língua desenvolve língua pilosa amarelada.", fonte: f(GON, 'Gurvits GE, Tan A, Língua pilosa negra, World J Gastroenterol 2014') },
  { t: "se associam a doença cardiovascular, hipertensão e fumo", p: "As varizes linguais são veias do ventre da língua que perderam a elasticidade da parede e se dilataram. Pressão alta, doença do coração e fumo também afetam a parede dos vasos, e por isso aparecem juntos. Um estudo sueco acompanhou pacientes por 8 anos e confirmou a associação. Ex.: dentista que vê varizes linguais num idoso pergunta na anamnese se ele mede a pressão e se tem problema de coração.", fonte: f('Bergh H et al., Varicosidades sublinguais, BMC Oral Health 2022', MAN) },
  { t: "Pigmento (melanina, amálgama) não esvazia", p: "A vitropressão empurra o sangue que circula dentro dos vasos, e por isso a lesão vascular fica pálida. A melanina fica presa dentro das células e o amálgama fica preso no tecido conjuntivo: a pressão não tira nenhum dos dois do lugar, e a cor continua igual. Ex.: o dentista aperta uma mancha azul no lábio com um tubete de anestésico de vidro; ela não muda de cor, então não é vascular.", fonte: f(MAN, NEV) },
  { t: "o agente inflama a parede do vaso", p: "O agente esclerosante (oleato de monoetanolamina) agride o endotélio, a camada que reveste o vaso por dentro. Forma-se inflamação e um coágulo, e depois o corpo substitui aquele vaso por tecido fibroso, que fecha a lesão. Por isso a lesão encolhe e fica mais firme sem precisar cortar. Ex.: hemangioma pequeno no lábio tratado com 2 ou 3 sessões de escleroterapia some sem cirurgia.", fonte: f(MAN, 'Siqueira AS et al., Escleroterapia de hemangioma, Research, Society and Development 2020') },
  { t: "a biópsia pode ser desnecessária", p: "Quando a mancha tem cor típica (azul-acinzentada), há amálgama por perto e a radiografia mostra os fragmentos radiopacos, o diagnóstico de tatuagem por amálgama está praticamente confirmado. Fazer biópsia nesse caso seria uma cirurgia sem ganho. Se faltar algum critério, a biópsia volta a ser indicada para afastar melanoma. Ex.: mancha ao lado de um amálgama antigo com pontinhos brancos na periapical: só anotar e acompanhar.", fonte: f(MAN, GON) },
  { t: "dois terços dos casos na boca ficam no palato duro", p: "O nevo azul é formado por melanócitos que ficaram mais fundos no tecido conjuntivo durante o desenvolvimento, e o palato duro é a região da boca onde isso mais acontece. A cor azul vem da luz refletida pelo pigmento profundo (o mesmo efeito de uma tatuagem). Ex.: mácula azul-escura de 4 mm no palato de uma mulher sem amálgama: o nevo azul entra nas hipóteses de diagnóstico, e a biópsia afasta melanoma.", fonte: f(GON, NEV) },
  { t: "gordura vista através da mucosa", p: "O lipoma é feito de tecido adiposo, que é amarelo. Quando ele fica logo abaixo da mucosa, que é fina e um pouco translúcida, a cor amarela aparece por transparência. Se está mais fundo, a mucosa mais grossa por cima esconde a cor e o nódulo fica rosado. Ex.: nódulo mole e amarelado na bochecha da Dona Cida, que cresce devagar há anos: lipoma superficial.", fonte: f(NEV, 'Schafer DR, Glass SH, Lesões amarelas, Head Neck Pathol 2019') },
  { t: "Gordura é menos densa que o formol", p: "O formol a 10% é quase todo água, e a gordura é mais leve que a água (por isso o óleo boia na sopa). Uma peça cheia de tecido adiposo, como o lipoma, flutua no frasco do fixador, enquanto peças de fibroma, músculo ou epitélio afundam. É um 'teste' que reforça o diagnóstico antes do laudo. Ex.: na clínica, o aluno coloca o fragmento no formol e ele fica boiando: o professor já comenta 'deve ser lipoma'.", fonte: f(NEV, 'Marques DO et al., Lipoma em mucosa jugal, UNINGÁ Review 2014') },
  { t: "A cor amarelada vem do tecido linfoide", p: "A boca tem pequenos acúmulos de tecido linfoide (como amígdalas em miniatura) no assoalho e na língua. No cisto linfoepitelial, um pedaço de epitélio fica preso nesse tecido e forma uma cavidade cheia de queratina e células. O conjunto tem cor branco-amarelada e aparece através da mucosa fina do assoalho. Ex.: nódulo pequeno amarelado ao lado do freio da língua, indolor: cisto linfoepitelial, removido com biópsia excisional.", fonte: f('Schafer DR, Glass SH, Lesões amarelas, Head Neck Pathol 2019', NEV) },
  { t: "o amarelo vem do pus (purulência) e da necrose", p: "O pus é formado por neutrófilos mortos, bactérias e restos de tecido, e tem cor amarelada; a necrose (tecido morto) também tende ao amarelo-acinzentado. Quando há infecção, como num abscesso de dente sem vitalidade, esse material se acumula e aparece pela mucosa. Ex.: nódulo na gengiva com ponto amarelo que solta secreção ao apertar = fístula de um dente necrosado: trata-se o dente, não a gengiva.", fonte: f('Schafer DR, Glass SH, Lesões amarelas, Head Neck Pathol 2019', NEV) },
  { t: "O dentista não trata isso na boca: reconhece e encaminha", p: "A icterícia é um sinal de doença do fígado, das vias biliares ou do sangue: a bilirrubina sobe no sangue e se deposita em tecidos ricos em fibras elásticas, como a mucosa e o branco dos olhos. Não é uma mácula de lesão local: a causa está fora da boca, então o papel do dentista é reconhecer o sinal e mandar para o médico. Ex.: paciente com mucosa e olhos amarelados é encaminhado ao clínico geral antes de qualquer cirurgia, porque a doença do fígado pode causar discrasia sanguínea e sangramento.", fonte: f('Schafer DR, Glass SH, Lesões amarelas, Head Neck Pathol 2019', NEV) },
  { t: "o amarelo ajuda a pensar na origem", p: "Cada coisa que dá cor amarela vem de uma estrutura diferente: gordura (lipoma), glândula sebácea (grânulos de Fordyce), tecido linfoide (cisto linfoepitelial), pus (abscesso, fístula), fibrina (fundo de úlcera) e bilirrubina (icterícia). Saber isso transforma a cor numa pista para as hipóteses de diagnóstico. Ex.: pontinhos amarelos agrupados na bochecha = sebácea (Fordyce); nódulo amarelo mole = gordura (lipoma).", fonte: 'Schafer DR, Glass SH, Lesões amarelas, Head Neck Pathol 2019' },
  { t: "o halo vermelho é a inflamação", p: "Em volta da úlcera, os vasos do tecido conjuntivo se dilatam por causa da inflamação (para trazer células de defesa), e a mucosa ali fica vermelha. Por isso a afta tem fundo amarelado (fibrina sobre a ferida) cercado por um anel vermelho. Ex.: na afta do lábio, o centro é amarelo e a borda é vermelha e dolorida ao toque.", fonte: f(NEV, MAN) },
  { t: "as papilas atrofiam e a língua fica lisa", p: "O epitélio da língua se renova muito rápido e precisa de vitamina B12 e ácido fólico para fabricar DNA das células novas. Na falta deles (anemia megaloblástica), as células não se dividem direito, o epitélio afina e as papilas filiformes somem. O dorso da língua fica vermelho, liso e ardido. Ex.: paciente vegano estrito há anos, cansado e pálido, com língua lisa: o dentista sugere ao médico pedir dosagem de B12.", fonte: f('McNamara KK, Kalmar JR, Lesões vermelhas e vasculares, Head Neck Pathol 2019', NEV) },
  { t: "Clinicamente se parecem; o diagnóstico é histopatológico", p: "Granuloma piogênico e lesão periférica de células gigantes são as duas massas vermelhas que sangram fácil na gengiva, e a cor, o tamanho e a superfície se sobrepõem. A diferença está nas células: muitos vasos no primeiro, células gigantes multinucleadas no segundo. Só o exame histopatológico mostra. Ex.: lesão vermelha no rebordo após extração é removida com biópsia excisional, e o laudo diz qual das duas era.", fonte: f(MAN, NEV) },
  { t: "o adenoma pleomórfico é o mais comum", p: "Entre os tumores de glândula salivar, o adenoma pleomórfico é o mais frequente, tanto nas maiores (parótida) quanto nas menores; e o palato é o local preferido nas glândulas menores, porque tem muitas delas. É benigno, mas cresce devagar e pode recidivar se não for removido inteiro, por isso a biópsia vem antes da cirurgia definitiva. Ex.: nódulo firme no palato de uma mulher de 44 anos, crescendo devagar: o adenoma pleomórfico é a primeira hipótese.", fonte: f(NEV, INCA) },
  { t: "não dá para separar de um tumor maligno", p: "Enquanto o tumor está embaixo de uma mucosa intacta, tanto o benigno quanto o maligno (como o carcinoma mucoepidermoide ou o adenoide cístico) aparecem como nódulo firme coberto por mucosa normal. A palpação e a cor não diferenciam. Só a biópsia mostra as células. Ex.: dois nódulos iguais no palato: um era adenoma pleomórfico e outro carcinoma adenoide cístico; o laudo é que mudou o tratamento.", fonte: f(INCA, NEV) },
  { t: "pode regredir com o ajuste da prótese", p: "Enquanto a hiperplasia fibrosa inflamatória é pequena, boa parte dela é inflamação (edema e vasos), que diminui quando a borda da prótese para de machucar. A lesão maior já tem muito colágeno, que não some, e por isso precisa de cirurgia além do ajuste. Ex.: pequena prega no fundo de vestíbulo some depois que o dentista alivia a borda da dentadura; a prega grande precisa ser removida.", fonte: f(MAN, INCA) },

  /* ---------- Manual: vasculares e biópsia ---------- */
  { t: "a pressão diminui o sangue no local", p: "A lesão vascular é um 'saco' de vasos cheios de sangue circulando. Ao apertar com vidro transparente (diascopia), o sangue é empurrado para fora dos vasos da área comprimida, e o que se vê pelo vidro é o tecido sem sangue: esbranquiçado. Ao soltar, ele volta. Ex.: no hemangioma do lábio, o dentista aperta com um tubete de anestésico de vidro e a lesão fica pálida na hora.", fonte: f(MAN, NEV) },
  { t: "causa hemorragia intensa", p: "Uma lesão vascular é feita de muitos vasos dilatados e cheios de sangue, às vezes ligados a vasos maiores. Ao cortar, não há como fechar tantos vasos de uma vez, e o sangramento pode ser difícil de controlar no consultório. Por isso primeiro se confirma pela diascopia, se avalia a extensão (às vezes com exame de imagem) e se prefere escleroterapia. Ex.: tentar biopsiar um hemangioma da língua com bisturi pode virar uma hemorragia de emergência.", fonte: f(MAN, NEV) },
  { t: "Sem queixa de sangramento ou estética, pode-se só acompanhar", p: "Muitas lesões vasculares pequenas são benignas e ficam estáveis por anos. Tratar tem riscos (sangramento, dor, inflamação da escleroterapia). Se a lesão não sangra, não incomoda e o paciente não se importa com a aparência, acompanhar é mais seguro. Ex.: lago venoso pequeno no lábio de um idoso, sem queixa: anotar, fotografar e reavaliar na próxima consulta.", fonte: MAN },
  { t: "cresce rápido e depois regride", p: "O hemangioma da infância é um tumor de células do endotélio: nos primeiros meses de vida essas células se multiplicam rápido (fase proliferativa), e depois, por motivos que ainda se estudam, param e vão sendo substituídas por gordura e tecido fibroso (involução), ao longo de anos. A malformação vascular não tem células se multiplicando; são vasos mal formados, por isso não regride. Ex.: bebê com mancha vermelha no lábio que cresce até 1 ano e clareia até os 7.", fonte: f(MAN, NEV) },
  { t: "persiste e acompanha o crescimento", p: "Na malformação vascular, os vasos já nascem com a estrutura alterada. Não é um tumor que prolifera e depois para: os vasos crescem junto com o corpo e podem dilatar mais com o tempo (trauma, hormônios). Por isso não regride sozinha e às vezes precisa de escleroterapia ou cirurgia. Ex.: adulto com lesão arroxeada no lábio desde criança, que foi aumentando com a idade.", fonte: f(MAN, NEV) },
  { t: "nasce do tecido linfático", p: "O linfangioma é uma malformação dos vasos linfáticos, que levam a linfa (líquido claro) e não sangue. Na superfície da língua, esses vasos dilatados aparecem como bolinhas transparentes agrupadas, lembrando vesículas ou 'ovas de peixe'. Às vezes há sangue misturado e algumas ficam arroxeadas. Ex.: criança com língua aumentada e superfície pedregosa com bolhinhas claras desde o nascimento.", fonte: f(MAN, NEV) },
  { t: "diagnóstico clínico já definitivo", p: "A biópsia é feita para descobrir o que a lesão é. Se o aspecto clínico já fecha o diagnóstico com segurança (por exemplo, língua geográfica, grânulos de Fordyce, tórus), cortar tecido não traz informação nova e só expõe o paciente a uma cirurgia. Ex.: paciente com grânulos de Fordyce típicos: o dentista explica que é normal e não faz biópsia.", fonte: MAN },
  { t: "Mesmo lesão pequena, se houver suspeita de malignidade, faz-se incisional", p: "Se a lesão for câncer, o cirurgião de cabeça e pescoço precisa ver o tamanho e o local originais para planejar a cirurgia com margem de segurança. Remover tudo numa biópsia excisional no consultório, sem margem, pode deixar células para trás e apagar as referências do tumor. Por isso, na suspeita de malignidade, tira-se só um fragmento para o diagnóstico. Ex.: úlcera endurecida de 8 mm na borda da língua: biópsia incisional e encaminhamento.", fonte: f(MAN, INCA) },
  { t: "a remoção é o tratamento", p: "Nas lesões reacionais benignas e pequenas, como o fibroma, tirar a lesão inteira já resolve o problema e, ao mesmo tempo, manda o material para o exame histopatológico confirmar. Uma cirurgia só faz as duas coisas: diagnóstico e tratamento. Ex.: fibroma de 6 mm na bochecha removido com biópsia excisional; o laudo confirma 'hiperplasia fibrosa' e o paciente já está tratado.", fonte: MAN },
  { t: "Área de necrose tem tecido amorfo", p: "Na necrose, as células morreram e se desfizeram: ao microscópio aparece só uma massa sem forma, sem núcleos nem arquitetura. O patologista não consegue dizer que tecido era nem se havia câncer ali. O fragmento precisa vir de tecido vivo, na borda ou na transição com a mucosa normal. Ex.: num carcinoma ulcerado, o fragmento é tirado da borda endurecida, não do fundo amarelado necrótico.", fonte: f(MAN, NEV) },
  { t: "Em concentração maior queima por fora", p: "O formol fixa o tecido 'amarrando' as proteínas. Concentrado demais, ele fixa a superfície muito rápido e cria uma casca que impede o próprio formol de entrar no centro da peça, que fica sem fixar e apodrece. O formol a 10% penetra num ritmo que fixa a peça inteira por igual. Ex.: fragmento colocado em formol puro chega ao laboratório com a borda dura e o centro estragado.", fonte: MAN },
  { t: "volume 10 a 20 vezes maior", p: "Enquanto fixa, o formol vai sendo 'gasto' ao se ligar às proteínas da peça. Se tiver pouco líquido, ele acaba antes de fixar tudo e o centro do fragmento se degrada. Com volume 10 a 20 vezes maior que a peça, sobra fixador. Ex.: fragmento de 0,5 cm vai num frasco com uns 10 mL de formol a 10%, nunca com só umas gotas.", fonte: MAN },
  { t: "Anestesiar na borda evita artefato", p: "Se o anestésico é injetado dentro da lesão, o líquido separa e distorce as células e as camadas (artefato), e o patologista pode ver o tecido 'inchado' e diferente do real. Injetando em volta, na borda, o nervo é bloqueado sem mexer no fragmento que vai ser examinado. Ex.: na biópsia de um fibroma, o dentista faz pequenas punções ao redor e não no centro do nódulo.", fonte: MAN },
  { t: "O eletrocautério queima o tecido", p: "O bisturi elétrico corta com calor, que coagula e carboniza as proteínas da borda do corte. Num fragmento pequeno de biópsia, essa área queimada pode ser quase a peça toda, e o patologista não consegue ver as células. Por isso o fragmento se tira com bisturi de lâmina, e o eletrocautério só serve para estancar sangramento depois. Ex.: biópsia de leucoplasia feita com eletrocautério volta com laudo 'material inadequado por artefato térmico'.", fonte: MAN },
  { t: "o pinçamento cria artefatos", p: "A pinça com dentes esmaga o tecido, rompendo e achatando as células no ponto em que segura. No microscópio isso pode parecer alteração de verdade ou esconder uma displasia epitelial. O certo é segurar a peça com delicadeza, de preferência por uma ponta, ou com um fio de sutura passado nela. Ex.: o aluno aperta o fragmento com a pinça de dente de rato e o laudo vem com 'artefato de esmagamento'.", fonte: MAN },
  { t: "A mandíbula é a mais afetada", p: "A mandíbula tem osso mais denso, com menos vasos sanguíneos que a maxila, e mucosa fina sobre áreas de muita força mastigatória (como a região lingual de molares). Como os antirreabsortivos diminuem a renovação do osso, a mandíbula, que já se recupera com mais dificuldade, é a mais atingida pela osteonecrose por medicamentos depois de uma extração ou trauma. Ex.: paciente com bisfosfonato na veia extrai um molar inferior e o alvéolo não cicatriza, ficando com osso exposto.", fonte: f(MAN, NEV) },
  { t: "por mais de 8 semanas", p: "Uma ferida normal na boca, mesmo de extração, cicatriza e cobre o osso em poucas semanas. O prazo de 8 semanas foi definido para separar a demora comum da cicatrização da osteonecrose por medicamentos: se o osso continua exposto depois disso, o problema é o osso que não se renova. Ex.: paciente que usa denosumabe e está com osso exposto no alvéolo 3 meses depois da extração preenche esse critério.", fonte: f(MAN, 'AAOMS, Medication-Related Osteonecrosis of the Jaw, 2022') },
  { t: "sem radioterapia na região", p: "A radioterapia de cabeça e pescoço também mata osso, porque destrói vasos e células ósseas: é a osteorradionecrose, outra doença, com outro manejo. Para chamar de osteonecrose por medicamentos, é preciso que o osso exposto seja explicado pelo remédio (bisfosfonato, denosumabe), e não pela radiação. Ex.: paciente que fez radioterapia para câncer de laringe e tem osso exposto na mandíbula: é osteorradionecrose, mesmo se tomar bisfosfonato.", fonte: f(MAN, 'AAOMS, Medication-Related Osteonecrosis of the Jaw, 2022') },

  /* ---------- Resumo ---------- */
  { t: "gengiva inserida, palato duro e dorso da língua", p: "São as regiões que levam o atrito da mastigação: a comida raspa no palato, na gengiva presa ao osso e no dorso da língua. Por isso o epitélio delas tem uma camada de queratina na superfície, mais dura, como proteção. As outras áreas, móveis e menos atritadas, têm mucosa mais fina e sem essa camada. Ex.: a afta aparece no lábio por dentro (não queratinizado), e o herpes recorrente intraoral no palato duro (queratinizado).", fonte: f(KAT, MAN) },

  /* ---------- Dicionário ---------- */
  { t: "presentes em mais de 80% da população", p: "Os grânulos de Fordyce são tão frequentes que quase todo adulto tem alguns, principalmente depois da puberdade, quando as glândulas sebáceas crescem por causa dos hormônios. Algo que mais de 80% das pessoas têm é, por definição, variação anatômica normal, não doença. Ex.: numa turma da clínica da faculdade, quase todos os alunos encontram pontinhos amarelos na própria bochecha.", fonte: f(MAN, 'Alamri N et al., Grânulos de Fordyce, J Pharm Bioallied Sci 2024') },
  { t: "Só ocorre em áreas com dentes", p: "A linha alba é causada pela pressão e pela sucção da bochecha contra os dentes na altura em que eles se encontram. Sem dentes, não há o que pressionar a mucosa naquela linha, e ela não se forma (ou some). Ex.: paciente desdentado que usa prótese total geralmente não tem linha alba; um com dentes naturais e hábito de apertar tem a linha bem marcada.", fonte: MAN },
  { t: "Anomalia congênita mais comum da boca", p: "A língua fissurada tem um componente hereditário: a tendência a formar sulcos vem de família. Como afeta cerca de 6% das pessoas, é a alteração de desenvolvimento mais vista na boca, à frente de outras bem mais raras. Não é doença e não precisa de tratamento, só de boa higiene. Ex.: pai e filho com sulcos no dorso da língua.", fonte: f(MAN, 'Ehsan H et al., Língua fissurada, Clin Cosmet Investig Dent 2023') },
  { t: "o que pode levar 4 a 6 semanas", p: "A camada de queratina extra da queratose friccional precisa descamar aos poucos, à medida que o epitélio se renova (cada ciclo leva algumas semanas). Por isso, mesmo tirando a causa, a placa não some de um dia para o outro. Se depois desse prazo continuar, não era só atrito e precisa de biópsia. Ex.: grampo da prótese parcial ajustado em março; em abril a placa branca já está quase sumindo.", fonte: MAN },
  { t: "causada principalmente pelo calor crônico do tabaco", p: "O fumo, principalmente de cachimbo e cigarro de palha, joga ar muito quente direto no palato. O epitélio responde ao calor com mais queratina (fica branco), e o ducto de cada glândula salivar menor do palato inflama, aparecendo como pontinhos vermelhos no meio do branco. Ex.: senhor da roça que fuma cachimbo há décadas, com palato branco cheio de pontos vermelhos.", fonte: f(MAN, NEV) },
  { t: "Desaparece quando a pessoa para de fumar", p: "Como a estomatite nicotínica é uma reação ao calor e às substâncias da fumaça, sem alteração celular importante, ao parar de fumar o estímulo acaba e o epitélio volta ao normal em semanas. Se a lesão não regredir depois de parar, merece biópsia. Ex.: paciente que largou o cachimbo e volta 2 meses depois com o palato normal.", fonte: f(MAN, NEV) },
  { t: "Infecção fúngica mais comum da mucosa oral", p: "A Candida já vive na boca de muita gente (faz parte da microbiota), então basta um desequilíbrio (antibiótico, prótese, imunossupressão, xerostomia) para ela crescer. Os outros fungos que causam doença na boca precisam vir de fora e são raros. Por isso, quando se fala em fungo na boca, quase sempre é candidíase. Ex.: na clínica de prótese, a estomatite protética por Candida é vista toda semana.", fonte: f(MAN, SPC) },
  { t: "tirando a prótese na hora do bochecho", p: "O antifúngico em suspensão (nistatina) precisa encostar na mucosa e ficar uns minutos agindo. Com a prótese na boca, o palato fica coberto e o remédio não chega lá; além disso, a própria prótese também precisa ser limpa e tratada separadamente. Ex.: idosa orientada a tirar a dentadura, bochechar a nistatina e deixar a prótese de molho enquanto isso.", fonte: f(MAN, SPC) },
  { t: "ligada à perda de dimensão vertical", p: "Quando a boca fecha demais (prótese gasta, perda de dentes posteriores), a mucosa atrás do canto da boca fica dobrada, úmida e com saliva parada. Esse ambiente favorece a Candida a invadir o epitélio, que engrossa e forma a placa branca da candidose hiperplásica. Corrigir a dimensão vertical faz parte do tratamento. Ex.: paciente com prótese total de 20 anos, placa branca na comissura que não sai na gaze.", fonte: f(MAN, NEV) },
  { t: "mediada por linfócitos T", p: "No líquen plano oral, linfócitos T se juntam numa faixa logo abaixo do epitélio e atacam as células da camada basal, que morrem e deixam o epitélio alterado (estrias brancas ou erosões). Por isso a doença responde a corticoide, que diminui a ação desses linfócitos. Ex.: na biópsia de líquen plano, o patologista descreve 'infiltrado linfocitário em faixa' logo abaixo do epitélio.", fonte: f(MAN, NEV) },
  { t: "a erosiva, se dói, trata-se com corticóide", p: "Como a lesão é causada pelos linfócitos atacando o epitélio, o corticoide tópico (em gel ou bochecho) diminui essa inflamação e a dor. A forma reticular, sem dor, não precisa de remédio: tratar não traria ganho e o corticoide pode favorecer candidíase. Ex.: paciente com líquen plano erosivo que arde com comida temperada usa gel de corticoide nas crises e melhora.", fonte: f(MAN, NEV) },
  { t: "80 a 90% dos cânceres orais", p: "O manual da disciplina e o INCA dão números um pouco diferentes (80 a 90% e 90 a 95%) porque contam bases diferentes (só boca, ou boca com lábio e orofaringe). Nos dois casos a mensagem é igual: quase todo câncer de boca é carcinoma espinocelular (CEC), porque nasce do epitélio escamoso que reveste a boca. Ex.: na prova, não decore o número exato; lembre que é a grande maioria.", fonte: f(MAN, INCA) },
  { t: "na mucosa costuma ser mais avançado e agressivo que na pele", p: "Na pele, as pessoas veem a pinta mudar e procuram o médico. Na boca, ninguém olha o palato ou a gengiva com frequência, e o melanoma cresce escondido até ficar grande. Além disso, a mucosa tem muitos vasos e linfáticos, o que favorece metástase mais cedo. Ex.: melanoma de palato descoberto só quando a prótese começou a não encaixar, já grande.", fonte: f(MAN, INCA) },
  { t: "Diâmetro maior que 6 mm", p: "O ABCDE foi criado para a pele, onde a maioria dos nevos benignos tem menos de 6 mm (o tamanho de uma borracha de lápis). Lesões maiores têm mais chance de ser melanoma, porque o crescimento sem controle aumenta o tamanho. Não é regra absoluta: melanoma pequeno também existe, por isso na boca toda pigmentação nova vai para biópsia. Ex.: mancha negra de 1,5 cm no palato preenche o 'D' e mais três letras do ABCDE.", fonte: MAN },
  { t: "pode corroer o osso", p: "A lesão periférica de células gigantes nasce do ligamento periodontal e do periósteo, coladinha ao osso alveolar. Suas células gigantes são parecidas com osteoclastos (as células que reabsorvem osso), por isso podem reabsorver a superfície do osso embaixo, deixando uma 'concavidade' visível na radiografia. Ex.: na periapical, aparece uma área de reabsorção em 'taça' no rebordo, embaixo da lesão vermelha; a biópsia confirma.", fonte: f(MAN, NEV) },
  { t: "Pode deslocar dentes", p: "O fibroma ossificante periférico nasce na gengiva entre os dentes (papila) e tem tecido mineralizado dentro, o que o deixa firme. Ao crescer ali, ele empurra os dentes vizinhos e pode abrir espaço entre eles. Já o granuloma piogênico, mole e vascular, raramente desloca dentes. Ex.: adolescente com nódulo firme na papila entre os incisivos superiores, que vão se afastando com o tempo.", fonte: f(MAN, NEV) },
  { t: "não desloca dentes", p: "O granuloma piogênico é um tecido mole, cheio de vasos e frágil, que cresce para fora (geralmente pediculado), sem força para empurrar os dentes. Isso ajuda a separar do fibroma ossificante periférico, que é firme e pode afastar os dentes. Ex.: lesão vermelha grande na gengiva de gestante, mas os dentes continuam no lugar.", fonte: f(MAN, NEV) },
  { t: "induzido pelo HPV", p: "Alguns tipos de papilomavírus humano (HPV de baixo risco, como 6 e 11) infectam as células do epitélio e as fazem se multiplicar, formando projeções em forma de dedo ou couve-flor: o papiloma. Esses tipos não estão ligados ao câncer. Ex.: lesão branca em forma de verruga no palato mole de um adulto é removida por biópsia excisional, e o laudo confirma papiloma escamoso.", fonte: f(MAN, NEV) },
  { t: "raramente precisa de biópsia", p: "A úlcera traumática tem causa visível (dente quebrado, mordida, prótese) e cicatriza em poucos dias a duas semanas quando a causa é removida. Essa resposta já confirma o diagnóstico sem cirurgia. A biópsia fica para a que não cicatriza em até 3 semanas. Ex.: úlcera na língua ao lado de dente quebrado: o dentista alisa o dente e ela some em 10 dias, sem biópsia.", fonte: f(MAN, MS) },
  { t: "duram meses e deixam cicatriz", p: "A afta maior é mais funda: a perda de tecido chega a camadas profundas do tecido conjuntivo. Para fechar uma ferida funda, o corpo precisa formar colágeno novo, o que demora (semanas a meses) e deixa cicatriz, como na pele. A afta menor é rasa e cura sem marca. Ex.: paciente com úlcera de 1,5 cm no palato mole há 6 semanas, muito dolorida, que cicatriza deixando uma retração.", fonte: f(MAN, 'StatPearls: Recurrent Aphthous Stomatitis (NBK431059)') },
  { t: "úlcera crônica, endurecida e indolor", p: "Na tuberculose oral, a bactéria provoca uma inflamação crônica com granulomas, que endurece o tecido e destrói devagar a mucosa. Por ser lenta, a úlcera não dói muito e não cicatriza, parecendo um carcinoma. Por isso a biópsia é importante: ela separa tuberculose de câncer. Ex.: paciente com tosse há meses e úlcera endurecida no dorso da língua: biópsia e encaminhamento ao médico.", fonte: f(MAN, NEV) },
  { t: "que pode perfurar o palato", p: "Na sífilis terciária, anos depois da infecção não tratada, forma-se a goma: uma inflamação crônica que destrói o tecido no meio (necrose). No palato, a goma destrói mucosa e osso e pode abrir uma comunicação entre boca e nariz. Ex.: paciente com voz anasalada e líquido saindo pelo nariz ao beber, com perfuração no palato: sorologia para sífilis entra nos exames.", fonte: f(MAN, NEV) },
  { t: "Drenar não resolve", p: "A mucocele é muco que vazou de um ducto rompido de uma glândula salivar menor. Drenar com agulha tira o muco daquele momento, mas a glândula continua produzindo e o ducto continua rompido: em dias a bolha enche de novo. É preciso remover a lesão junto com as glândulas envolvidas e mandar para o exame histopatológico. Ex.: rapaz que furou a mucocele em casa e ela voltou igual na semana seguinte.", fonte: f(MAN, NEV) },
  { t: "geralmente em crianças de 3 meses a 6 anos", p: "Antes dos 3 meses, o bebê ainda tem anticorpos que vieram da mãe pela placenta e protegem contra o herpes simples. Depois eles acabam, e a criança pequena, que leva tudo à boca e convive com adultos que têm herpes labial, pega o vírus pela primeira vez. Ex.: criança de 2 anos que ganhou beijo de um parente com herpes labial e dias depois teve febre e a boca cheia de úlceras.", fonte: f(MAN, NEV) },
  { t: "que pode matar se não for tratada", p: "No pênfigo vulgar, anticorpos atacam as proteínas que grudam as células do epitélio umas nas outras. A pele e as mucosas descolam em áreas grandes, como uma queimadura extensa: o corpo perde líquido, proteína e fica aberto a infecções. Antes dos corticoides, a maioria dos pacientes morria. Ex.: paciente com erosões que só aumentam na boca e depois na pele precisa de diagnóstico rápido e corticoide sistêmico.", fonte: f(MAN, NEV) },
  { t: "as lesões da boca costumam vir antes das da pele", p: "No pênfigo vulgar, a boca é atingida primeiro na maioria dos pacientes, muitas vezes meses antes da pele. O dentista pode ser o primeiro profissional a ver a doença, e reconhecê-la cedo permite tratar antes que ela se espalhe. Ex.: paciente com erosões doloridas na gengiva e na bochecha que não cicatrizam, sem nada na pele ainda: o sinal de Nikolsky positivo e a biópsia levam ao diagnóstico.", fonte: f(MAN, NEV) },
  { t: "As bolhas são mais profundas e duram mais que no pênfigo", p: "No penfigóide benigno das mucosas, os anticorpos atacam a ligação entre o epitélio e a membrana basal, embaixo de todo o epitélio. A bolha se forma por baixo do epitélio inteiro, com teto grosso, que aguenta mais tempo antes de romper. No pênfigo vulgar, a separação acontece dentro do epitélio, o teto é fino e rompe logo. Ex.: no penfigóide às vezes se vê a bolha inteira na gengiva; no pênfigo quase só se veem erosões.", fonte: f(MAN, NEV) },
  { t: "característico, mas não exclusivo", p: "O sinal de Nikolsky aparece quando as células do epitélio estão mal grudadas e qualquer atrito lateral separa as camadas. Isso é típico do pênfigo vulgar, mas também pode acontecer em outras doenças bolhosas (como o penfigóide) e em queimaduras graves. Por isso o sinal sugere, mas o diagnóstico vem da biópsia. Ex.: o dentista esfrega de leve uma área de mucosa normal com o cabo do espelho e ela forma bolha: pensa em pênfigo e pede biópsia.", fonte: f(MAN, NEV) },
  { t: "mudar o plano de tratamento", p: "Se as petéquias e equimoses não vêm de trauma, podem indicar que o sangue não coagula bem (plaquetas baixas, leucemia, uso de anticoagulante). Uma extração ou raspagem nesse paciente pode dar hemorragia grave. O dentista adia o procedimento e encaminha para exames antes. Ex.: adolescente com pontinhos roxos no palato, gengiva sangrando e cansaço: hemograma antes de qualquer cirurgia.", fonte: MAN },
  { t: "por ser mais potente", p: "Na veia, o bisfosfonato chega todo ao sangue e se acumula muito no osso, em doses altas (como no tratamento de metástases ósseas e mieloma). Por boca, só uma fração pequena é absorvida no intestino. Mais remédio no osso = renovação óssea mais travada = mais risco de osteonecrose por medicamentos depois de uma extração. Ex.: paciente com câncer de mama e metástase óssea que recebe ácido zoledrônico na veia tem risco bem maior que uma senhora que toma alendronato por boca.", fonte: f(MAN, 'AAOMS, Medication-Related Osteonecrosis of the Jaw, 2022') },
  { t: "Lesão comum em pessoas com HIV", p: "O sarcoma de Kaposi é causado pelo herpesvírus humano 8 (HHV-8), que só consegue provocar o tumor quando a imunidade está muito baixa. Como o HIV destrói os linfócitos T, que controlam esse vírus, ele aparece muito na aids sem tratamento. Na boca, o palato é o local mais comum. Ex.: mancha arroxeada no palato de um paciente com aids: biópsia e encaminhamento.", fonte: f(MAN, NEV) },
  { t: "pode ser lesão inicial da infecção pelo HIV", p: "A leucoplasia pilosa é causada pelo vírus Epstein-Barr, que quase todo adulto já tem, mas que só consegue se multiplicar no epitélio da língua quando há imunossupressão. Por isso, ver leucoplasia pilosa num paciente sem diagnóstico pode ser o primeiro sinal de HIV, e o dentista deve orientar o teste. Ex.: rapaz de 25 anos com estrias brancas verticais na borda da língua que não saem na raspagem: encaminhar para sorologia.", fonte: f(MAN, NEV) },
  { t: "Biópsia não quer dizer que é maligno", p: "A biópsia é só uma forma de olhar o tecido ao microscópio. Muitas lesões benignas são biopsiadas, e às vezes a própria biópsia excisional já é o tratamento, como no fibroma. Explicar isso ao paciente diminui o medo e ajuda a aceitar o procedimento. Ex.: paciente assusta ao ouvir 'vamos fazer biópsia'; o dentista explica que é para confirmar um fibroma e tirar de uma vez.", fonte: MAN },
  { t: "porque não mostra a invasão do tecido", p: "A citologia esfoliativa pega só as células soltas da superfície. O que define o carcinoma é a invasão das células alteradas para o tecido conjuntivo embaixo do epitélio, e isso só se vê numa peça com profundidade, ou seja, num fragmento de biópsia. Por isso a citologia pode até levantar suspeita, mas não confirma nem descarta câncer. Ex.: citologia 'normal' de uma úlcera endurecida não tranquiliza: a biópsia incisional ainda é obrigatória.", fonte: f(MAN, NEV) },
  { t: "Sem saliva, a Candida e as cáries aumentam", p: "A saliva lava a boca, tem substâncias antimicrobianas (como lisozima e anticorpos), neutraliza ácidos e repõe minerais no esmalte. Com xerostomia, o biofilme fica parado, o pH cai e as defesas diminuem: a Candida e as bactérias da cárie crescem. Ex.: paciente que fez radioterapia de cabeça e pescoço, com boca seca, tem candidíase de repetição e cáries no colo dos dentes.", fonte: NEV },
  { t: "bochechar água depois da bombinha", p: "A bombinha de corticoide deixa parte do remédio grudada na boca e na garganta. Ali, o corticoide baixa a defesa local da mucosa e deixa a Candida crescer. Bochechar e cuspir água tira esse resto do remédio da boca. Ex.: criança asmática com placas brancas no palato que somem quando ela passa a bochechar depois de cada uso da bombinha.", fonte: f(MAN, NEV) },
  { t: "lábio inferior e ponta da língua para submentonianos", p: "A linfa de cada região corre por vasos linfáticos até o grupo de linfonodos mais próximo. O lábio inferior e a ponta da língua ficam bem na frente, então drenam para os linfonodos embaixo do queixo (submentonianos); a língua e o assoalho drenam para os submandibulares e cervicais. Saber isso diz onde palpar e onde procurar metástase do carcinoma epidermoide. Ex.: câncer de lábio inferior: o dentista palpa primeiro embaixo do queixo.", fonte: NEV },
  { t: "Só se trata (com antifúngico) se houver infecção por Candida", p: "A glossite rombóide mediana é uma área do dorso da língua sem papilas, muitas vezes ligada à Candida. Se não há sintoma nem infecção ativa, ela é só uma mancha benigna e não precisa de remédio. Quando há Candida (ardência, placas), o antifúngico resolve a infecção. Ex.: fumante com área vermelha em losango no meio da língua que arde: nistatina e parar de fumar.", fonte: f(MAN, NEV) },
  { t: "pode causar obstrução das vias aéreas", p: "A tonsila lingual é tecido linfoide, como as amígdalas, e cresce quando há infecção ou inflamação crônica. Como fica na base da língua, junto à entrada da garganta, um aumento grande pode estreitar a passagem do ar e atrapalhar engolir ou respirar, principalmente deitado; se cresce só de um lado, faz-se biópsia para afastar tumor. Ex.: paciente com ronco forte e sensação de 'bola na garganta' por tonsila lingual aumentada é encaminhado ao otorrinolaringologista.", fonte: f(MAN, NEV) },
  { t: "tratamento com remoção total e controle", p: "Mesmo que a biópsia não mostre displasia epitelial, a leucoplasia é potencialmente maligna e pode mudar com o tempo. Remover a lesão inteira (cirurgia ou laser, depois da biópsia) diminui a área de risco, e o controle periódico pega a volta ou uma lesão nova cedo, porque o fumante continua exposto. Ex.: leucoplasia removida em 2025 é revista a cada 6 meses; uma nova placa no outro lado é biopsiada logo.", fonte: f(MAN, OMS) },
  { t: "exodontia e tratamento periodontal aumentam o risco", p: "A extração e a raspagem profunda machucam o osso, que precisa se renovar para cicatrizar. Em quem usa bisfosfonato ou denosumabe, essa renovação está travada, e o osso exposto não é coberto: começa a necrose. Por isso, antes de iniciar o remédio, o ideal é fazer as extrações necessárias; depois, evitar cirurgias e preferir tratamentos conservadores. Ex.: paciente que vai começar ácido zoledrônico passa antes pelo dentista para extrair dentes sem condição.", fonte: f(MAN, 'AAOMS, Medication-Related Osteonecrosis of the Jaw, 2022') },
  { t: "primeiro se faz diascopia e exame de imagem", p: "A diascopia confirma que a lesão é vascular (fica pálida), e o exame de imagem (ultrassom, ressonância) mostra até onde os vasos vão e se estão ligados a vasos maiores. Sem saber isso, cortar ou biopsiar pode dar hemorragia difícil de parar. Ex.: lesão arroxeada grande no lábio: diascopia positiva, ultrassom com Doppler e só depois decidir entre escleroterapia ou cirurgia em ambiente preparado.", fonte: f(MAN, NEV) },
  { t: "Soro, álcool e água estragam a peça", p: "Soro e água não fixam: as enzimas das próprias células continuam agindo e o tecido apodrece (autólise), e a água ainda faz as células incharem. O álcool fixa mas desidrata e encolhe o tecido, deformando as células. Só o formol a 10% preserva a arquitetura como estava. Ex.: fragmento mandado em soro fisiológico chega ao laboratório degradado e o laudo vem 'material autolisado'.", fonte: MAN },
  { t: "só se trata por estética", p: "A pigmentação fisiológica é só mais melanina produzida por melanócitos normais, sem risco de virar câncer nem sintoma. Não há doença para tratar. Se o paciente se incomoda com a cor da gengiva ao sorrir, existe a despigmentação (laser ou bisturi), feita só por estética. Ex.: jovem de pele morena que acha a gengiva 'escura' no sorriso pode fazer despigmentação, mas o dentista explica que é normal.", fonte: f(MAN, GON) },
  { t: "trauma crônico de baixa intensidade", p: "Um trauma forte machuca de uma vez e gera úlcera. Um trauma fraco e repetido (borda da prótese roçando todo dia) não chega a romper a mucosa, mas mantém uma inflamação constante que estimula a produção de tecido fibroso. Com o tempo, esse tecido se acumula e forma a hiperplasia fibrosa inflamatória. Ex.: dentadura frouxa que afunda um pouco a cada mordida, ao longo de anos, gera pregas no fundo de vestíbulo.", fonte: f(MAN, NEV) },
  { t: "tecido conjuntivo denso e pouco vascularizado", p: "O fibroma é formado principalmente por fibras de colágeno bem apertadas, com poucos vasos sanguíneos no meio. Isso explica a aparência e o comportamento: é firme ao toque, mais pálido que a mucosa ao redor e quase não sangra. É o contrário do granuloma piogênico, cheio de vasos. Ex.: o dentista aperta o nódulo da bochecha e ele é duro e claro: fibroma.", fonte: f(MAN, NEV) },
  { t: "local típico da pigmentação fisiológica", p: "A gengiva inserida tem melanócitos ativos na camada basal do epitélio, e em pessoas de pele mais escura eles produzem mais melanina ali. Por ser uma área exposta ao sorrir, é onde a pigmentação fisiológica mais aparece, geralmente como faixa simétrica. Ex.: em pacientes negros, a faixa marrom na gengiva inserida dos dentes anteriores é achado normal.", fonte: f(KAT, MAN) },
  { t: "Sobe para fechar a passagem para o nariz", p: "O palato mole é feito de músculos cobertos por mucosa e não tem osso por baixo como o palato duro, por isso se move. Ao engolir ou falar certos sons, os músculos o levantam contra a parede de trás da garganta, fechando a nasofaringe para a comida e o ar não subirem para o nariz. Ex.: em paciente com fenda palatina, o palato mole não fecha e o líquido volta pelo nariz.", fonte: KAT },
  { t: "uma das áreas de maior risco para o câncer de boca", p: "O assoalho tem mucosa fina e não queratinizada e fica no ponto mais baixo da boca, onde a saliva com as substâncias do tabaco e do álcool se acumula. O epitélio fino e muito exposto sofre mais dano no DNA. Por isso leucoplasia, eritroplasia e carcinoma epidermoide aparecem bastante ali. Ex.: no exame, o dentista pede ao paciente para tocar a ponta da língua no palato e olha o assoalho inteiro.", fonte: f(INCA, NEV) }
  ]);
})();
